1	import { redirect, notFound } from "next/navigation";
2	import { headers } from "next/headers";
3	
4	/**
5	 * Host gate: the admin portal is only reachable from the dedicated admin
6	 * hostname(s) in NXEON_ADMIN_HOSTS (comma-separated). On any other host — e.g.
7	 * the public nxeon.cloud — /admin 404s as if it doesn't exist. Empty/unset =
8	 * no host restriction (dev fallback). Returns true when access should be REFUSED.
9	 */
10	async function adminHostBlocked(): Promise<boolean> {
11	  const allow = (process.env.NXEON_ADMIN_HOSTS ?? "")
12	    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
13	  if (allow.length === 0) return false;
14	  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
15	  return !allow.includes(host);
16	}
17	import { realUser, impersonating } from "@/lib/auth";
18	import { isStaff, canAccessHref } from "@/lib/rbac";
19	import { db } from "@/lib/db";
20	import { getSetting, getSettingBool } from "@/lib/settings";
21	import { Shell, type NavSection } from "@/components/portal/Shell";
22	import { ADMIN_NAV } from "@/lib/admin-groups";
23	import { AdminSubTabs } from "@/components/admin/SubTabs";
24	import AdminChatNotifier from "@/components/admin/AdminChatNotifier";
25	
26	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
27	function isPlainIp(s: string): boolean {
28	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
29	}
30	
31	/**
32	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
33	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
34	 * parseable entries or the requester IP can't be determined, so a bad value can
35	 * never lock every admin out — only an exact match is ever enforced.
36	 * Returns true when access should be REFUSED.
37	 */
38	async function adminIpBlocked(): Promise<boolean> {
39	  const raw = await getSetting("allowed_admin_ips", "");
40	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
41	  if (entries.length === 0) return false; // no restriction configured
42	  const valid = entries.filter(isPlainIp);
43	  if (valid.length === 0) {
44	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
45	    return false; // malformed -> fail open
46	  }
47	  const hdrs = await headers();
48	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
49	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
50	  // client-supplied leftmost entry.
51	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
52	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
53	  if (!ip) {
54	    console.warn("[admin-ip] could not determine requester IP; failing open");
55	    return false;
56	  }
57	  return !valid.includes(ip);
58	}
