17	export function CommandPalette({ nav }: { nav: NavEntry[] }) {
18	  const [open, setOpen] = useState(false);
19	  const [q, setQ] = useState("");
20	  const [results, setResults] = useState<Result[]>([]);
21	  const [active, setActive] = useState(0);
22	  const router = useRouter();
23	  const inputRef = useRef<HTMLInputElement>(null);
24	  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
25	  // Where focus was when the palette opened, so closing it (Escape, click-away,
26	  // navigation) returns focus to the ⌘K trigger instead of dropping it to the
27	  // top of the document.
28	  const restoreFocus = useRef<HTMLElement | null>(null);
29	
30	  useEffect(() => {
31	    const onKey = (e: KeyboardEvent) => {
32	      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k") {
33	        e.preventDefault();
34	        setOpen((v) => !v);
35	      }
36	      if (e.key === "Escape") setOpen(false);
37	    };
38	    window.addEventListener("keydown", onKey);
39	    return () => window.removeEventListener("keydown", onKey);
40	  }, []);
41	
42	  useEffect(() => {
43	    if (open) {
44	      restoreFocus.current = (document.activeElement as HTMLElement) ?? null;
45	      setQ("");
46	      setResults([]);
47	      setActive(0);
48	      setTimeout(() => inputRef.current?.focus(), 30);
49	    } else {
50	      restoreFocus.current?.focus?.();
51	      restoreFocus.current = null;
52	    }
53	  }, [open]);
54	
55	  const navMatches: Result[] = q.length > 0
56	    ? nav
57	        .filter((n) => n.label.toLowerCase().includes(q.toLowerCase()))
58	        .slice(0, 5)
59	        .map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }))
60	    : nav.slice(0, 7).map((n) => ({ type: "page", label: n.label, sub: n.section, href: n.href }));
61	
62	  useEffect(() => {
63	    if (debounce.current) clearTimeout(debounce.current);
64	    if (q.length < 2) {
65	      setResults([]);
66	      return;
67	    }
68	    debounce.current = setTimeout(async () => {
69	      try {
70	        const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`);
71	        const json = await res.json();
72	        setResults(json.results ?? []);
73	      } catch {
74	        setResults([]);
75	      }
76	    }, 180);
77	  }, [q]);
78	
79	  const all = [...navMatches, ...results];
80	
81	  const go = useCallback(
82	    (href: string) => {
83	      setOpen(false);
84	      router.push(href);
85	    },
86	    [router]
87	  );
88	
89	  if (!open) return null;
90	
91	  return (
92	    <div
93	      className="fixed inset-0 z-50 flex items-start justify-center bg-black/60 p-4 pt-[12vh] backdrop-blur-sm"
94	      onClick={() => setOpen(false)}
95	    >
96	      <div
97	        role="dialog"
98	        aria-modal="true"
99	        aria-label="Command palette"
100	        className="glass w-full max-w-xl overflow-hidden shadow-2xl animate-fade-up"
101	        onClick={(e) => e.stopPropagation()}
102	      >
103	        <div className="flex items-center gap-3 border-b border-white/[0.08] px-4 py-3">
104	          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#64748b" strokeWidth="2">
105	            <circle cx="11" cy="11" r="7" />
106	            <path d="M21 21l-4-4" />
107	          </svg>
108	          <input
109	            ref={inputRef}
110	            aria-label="Search servers, domains, tickets and pages"
111	            className="w-full bg-transparent text-sm outline-none placeholder:text-slate-500"
112	            placeholder="Search servers, domains, tickets, pages…"
113	            value={q}
114	            onChange={(e) => {
115	              setQ(e.target.value);
116	              setActive(0);
117	            }}
118	            onKeyDown={(e) => {
119	              if (e.key === "ArrowDown") {
120	                e.preventDefault();
121	                setActive((a) => Math.min(a + 1, all.length - 1));
122	              }
123	              if (e.key === "ArrowUp") {
124	                e.preventDefault();
125	                setActive((a) => Math.max(a - 1, 0));
126	              }
127	              if (e.key === "Enter" && all[active]) go(all[active].href);
128	            }}
129	          />
130	          <span className="kbd">esc</span>
131	        </div>
132	        <div className="max-h-[50vh] overflow-y-auto p-2">
133	          {all.length === 0 ? (
134	            <p className="px-3 py-6 text-center text-sm text-slate-500">No results.</p>
135	          ) : (
136	            all.map((r, i) => (
137	              <button
138	                key={`${r.type}-${r.href}-${i}`}
139	                className={`flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm transition-colors ${
140	                  i === active ? "bg-brand-500/20 text-white" : "text-slate-300 hover:bg-white/[0.05]"
141	                }`}
142	                onMouseEnter={() => setActive(i)}
143	                onClick={() => go(r.href)}
144	              >
145	                <span className="w-5 text-center text-xs opacity-70">{typeIcons[r.type] ?? "→"}</span>
146	                <span className="flex-1 truncate">{r.label}</span>
147	                {r.sub && <span className="truncate text-xs text-slate-500">{r.sub}</span>}
148	              </button>
149	            ))
150	          )}
151	        </div>
152	      </div>
153	    </div>
154	  );
155	}
