3	import { useEffect, useRef } from "react";
4	
5	/**
6	 * Browser-side alert for support staff: while an admin tab is open, poll the
7	 * read-only unread live-chat count and, when it INCREASES, play a short beep and
8	 * fire a Web Notification. Mounted once in the admin layout so it covers every
9	 * admin page.
10	 *
11	 * Everything here is best-effort and defensive — a missing AudioContext, a
12	 * denied Notification permission, or a failed fetch must never throw or disrupt
13	 * the admin portal. It also never writes anything; it only reads a count.
14	 */
15	
16	const POLL_MS = 10_000;
17	
18	export default function AdminChatNotifier() {
19	  // Last count we've seen. `null` until the first successful poll, so the very
20	  // first load never fires an alert for messages that were already waiting.
21	  const lastCount = useRef<number | null>(null);
22	  // Debounce: suppress a second alert within this window even if the count keeps
23	  // climbing, so a burst of messages doesn't machine-gun the beep.
24	  const lastAlertAt = useRef(0);
25	
26	  useEffect(() => {
27	    let stopped = false;
28	    let timer: ReturnType<typeof setTimeout> | undefined;
29	
30	    // Ask for Web Notification permission once (guarded for unsupported/denied).
31	    try {
32	      if (typeof Notification !== "undefined" && Notification.permission === "default") {
33	        Notification.requestPermission().catch(() => {});
34	      }
35	    } catch {
36	      /* Notification API unavailable — ignore. */
37	    }
38	
39	    /** Short beep via the Web Audio API — no asset needed. Fails silently. */
40	    function beep() {
41	      try {
42	        const Ctx =
43	          (window as unknown as { AudioContext?: typeof AudioContext; webkitAudioContext?: typeof AudioContext })
44	            .AudioContext ??
45	          (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
46	        if (!Ctx) return;
47	        const ctx = new Ctx();
48	        const osc = ctx.createOscillator();
49	        const gain = ctx.createGain();
50	        osc.type = "sine";
51	        osc.frequency.value = 880;
52	        gain.gain.setValueAtTime(0.0001, ctx.currentTime);
53	        gain.gain.exponentialRampToValueAtTime(0.15, ctx.currentTime + 0.02);
54	        gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.35);
55	        osc.connect(gain);
56	        gain.connect(ctx.destination);
57	        osc.start();
58	        osc.stop(ctx.currentTime + 0.36);
59	        osc.onended = () => ctx.close().catch(() => {});
60	      } catch {
61	        /* AudioContext blocked or unavailable — ignore. */
62	      }
63	    }
64	
65	    /** Fire a Web Notification if permission was granted. Fails silently. */
66	    function notify(newCount: number) {
67	      try {
68	        if (typeof Notification === "undefined" || Notification.permission !== "granted") return;
69	        const n = new Notification("New live-chat message", {
70	          body: newCount > 1 ? `${newCount} conversations need a reply.` : "A visitor is waiting for a reply.",
71	          tag: "nxeon-chat-unread", // collapse duplicates into one bubble
72	          icon: "/favicon.ico",
73	        });
74	        n.onclick = () => {
75	          try {
76	            window.focus();
77	            window.location.href = "/admin/chat";
78	            n.close();
79	          } catch {
80	            /* ignore */
81	          }
82	        };
83	      } catch {
84	        /* ignore */
85	      }
86	    }
87	
88	    async function poll() {
89	      try {
90	        const res = await fetch("/api/admin/chat-unread", { cache: "no-store" });
91	        if (res.ok) {
92	          const data = (await res.json().catch(() => null)) as { count?: number } | null;
93	          const count = typeof data?.count === "number" ? data.count : 0;
94	          const prev = lastCount.current;
95	
96	          // Only alert on a genuine INCREASE, only when the tab is visible (the
97	          // card asks for alerts while the admin portal tab is open), and only
98	          // after a short debounce window.
99	          if (
100	            prev !== null &&
101	            count > prev &&
102	            typeof document !== "undefined" &&
103	            document.visibilityState === "visible" &&
104	            Date.now() - lastAlertAt.current > 4_000
105	          ) {
106	            lastAlertAt.current = Date.now();
107	            beep();
108	            notify(count);
109	          }
110	          lastCount.current = count;
111	        }
112	      } catch {
113	        /* Network/parse error — skip this tick, try again next interval. */
114	      } finally {
115	        if (!stopped) timer = setTimeout(poll, POLL_MS);
116	      }
117	    }
118	
119	    poll();
120	    return () => {
121	      stopped = true;
122	      if (timer) clearTimeout(timer);
123	    };
124	  }, []);
125	
126	  return null;
127	}
